class Solution {
public:
    int monkeyMove(int n) {
        long long MOD = 1e9 + 7;
        long long base = 2, exp = n, res = 1;
        while (exp > 0) {
            if (exp % 2 == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp /= 2;
        }
        return (res - 2 + MOD) % MOD;
    }
};

class Solution {
    public int monkeyMove(int n) {
        long MOD = 1_000_000_007L;
        long base = 2, exp = n, res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return (int)((res - 2 + MOD) % MOD);
    }
}

var monkeyMove = function(n) {
    const MOD = 1000000007n;
    let base = 2n, exp = BigInt(n), res = 1n;
    while (exp > 0n) {
        if (exp % 2n === 1n) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp /= 2n;
    }
    return Number((res - 2n + MOD) % MOD);
